class Outbox:
    def __init__(self, snapshot=None):
        if snapshot is None:
            self.items = {}
            self.enqueue_order = []
            self.dedup = {}
        else:
            self.items = copy.deepcopy(snapshot["items"])
            self.enqueue_order = copy.deepcopy(snapshot["enqueue_order"])
            self.dedup = copy.deepcopy(snapshot["dedup"])

    def enqueue(self, key, payload) -> bool:
        if not isinstance(key, str) or not key:
            raise ValueError("Key must be a non-empty string")

        payload_copy = copy.deepcopy(payload)
        payload_json = json.dumps(payload_copy, sort_keys=True)

        if key in self.dedup:
            if self.dedup[key] == payload_json:
                return False
            else:
                raise ValueError("Same key with different payload")
        else:
            self.dedup[key] = payload_json
            self.items[key] = {
                "payload": payload_copy,
                "version": 0,
                "worker": None,
                "lease_expiry": None,
                "completed": False
            }
            self.enqueue_order.append(key)
            return True

    def claim(self, worker, now, lease):
        if not isinstance(worker, str) or not worker:
            raise ValueError("Worker must be a non-empty string")

        if isinstance(lease, bool) or not isinstance(lease, (int, float)) or lease <= 0:
            raise ValueError("Lease must be > 0")

