            item = self.items[key]
            if item["completed"]:
                continue

            if item["lease_expiry"] is None or now >= item["lease_expiry"]:
                item["version"] += 1
                item["worker"] = worker
                item["lease_expiry"] = now + lease

                return {
                    "key": key,
                    "payload": copy.deepcopy(item["payload"]),
                    "version": item["version"]
                }

        return None

    def complete(self, key, worker, version, now) -> bool:
        if key not in self.items:
            return False

        item = self.items[key]

        if item["completed"]:
